Q: How can I bitwise-cast a 32-bit float into an integer without using typed arrays? A: <p>You can always construct the bit representation manually, using the logarithm to estimate the exponent, then multiplying the number by an appropriate power of two to extract the mantissa bits.  Something like this:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>// use exponentiation by squaring to avoid precision issues
// when Math.pow(base, n) is defined as Math.exp(n * Math.log(base))
function pow2(n) {
  if (-31 &lt;= n &amp;&amp; n &lt; 0)
    return 1 / (1 &lt;&lt; -n &gt;&gt;&gt; 0);
  if (0 &lt;= n &amp;&amp; n &lt;= 31)
    return 1 &lt;&lt; n &gt;&gt;&gt; 0;
  var semi = pow2(n &gt;&gt; 1);
  if (n &amp; 1)
    return 2 * semi * semi;
  return semi * semi;
}

var HALF_EPSILON    = 1 / (1 &lt;&lt; 24) / (1 &lt;&lt; 29);  //= 2↑−53
var HALF_EPSILON32  = 1 / (1 &lt;&lt; 24);              //= 2↑−24

function f32_to_u32(x) {
  if (x !== x)                 /* NaN */
    return 0x7fc00000;
  var signBit = x + (1 / x) &lt; 0 ? (1 &lt;&lt; 31 &gt;&gt;&gt; 0) : 0;

  x = Math.abs(x);
  if (x === 0)                 /* zero */
    return signBit;

  var exp, mantf;

  if (x === Infinity) {
    exp = Infinity;
    mantf = 0;
  } else {
    // use the logarithm to estimate the exponent part,
    // then refine the estimate to correct rounding errors
    exp = Math.round(Math.log(x) * Math.LOG2E);
    var mantd = x * pow2(-exp);

    mantd /= HALF_EPSILON;
    while (mantd !== Math.floor(mantd)) {
      mantd *= 2;
      exp--;
    }
    mantd *= HALF_EPSILON;

    while (mantd &gt;= 1) {
      mantd /= 2;
      exp++;
    }

    // round to 32-bit precision
    mantf = Math.round(mantd / HALF_EPSILON32) * HALF_EPSILON32;

    while (mantf &gt;= 1) {
      mantf /= 2;
      exp++;
    }
  }

  // extract the mantissa
  var mant;
  if (exp &gt; 128) {             /* infinities */
    mant = 0;
    exp = 129;
  } else if (exp &lt;= -126) {    /* denormals */
    mant = mantf / HALF_EPSILON32 * pow2(125 + exp);
    exp = -126;
  } else {
    mant = mantf / HALF_EPSILON32;
  }
  mant &amp;= 0x7fffff;
  exp = (exp + 126) &lt;&lt; 23;

  return (signBit | exp | mant) &gt;&gt;&gt; 0;
}

// test

{
  const f32_to_u32_ref = f =&gt;
    new Uint32Array(new Float32Array([f]).buffer)[0];

  const check = (f, u = f32_to_u32_ref(f)) =&gt; {
    const actual = f32_to_u32(f);
    if (actual !== u) {
      throw `f32_to_u32(${f}) = 0x${
        actual.toString(16)} ≠ 0x${
        u.toString(16)}`;
    }
  };

  check(0);
  check(-0);
  check(1);
  check(1.5);
  check(NaN);
  check(Infinity);
  check(-Infinity);

  for (var i = 0; i &lt; 64; ++i) {
    const r = Math.random();
    check(r);
  }

  const u32 = new Uint32Array([0]);
  const f32 = new Float32Array(u32.buffer);

  for (var x = 0; x &lt; 0xfffff; ++x) {
    u32[0] = ((((x &lt;&lt; 24) &gt;&gt; 24) &amp; 0xffffff) | ((x &amp; 0xfff00) &lt;&lt; 20)) &gt;&gt;&gt; 0;
    f32[0] = f32[0]; // normalize NaNs
    check(f32[0], u32[0]);
  }

  console.info('all tests passed');
}</code></pre>
